/**
 *
 * ChipStart component is a part of the Chip component.
 *
 * [Live Demo](https://www.primereact.org/chip/)
 *
 * @module ChipStart
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { ChipRootInstance } from './ChipRoot.types';
/**
 * Defines passthrough(pt) options type in ChipStart component.
 */
export type ChipStartPassThroughType<E> = PassThroughType<ChipStartInstance, E>;
/**
 * Defines passthrough(pt) options of ChipStart component.
 */
export interface ChipStartPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: ChipStartPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in ChipStart component.
 */
export interface ChipStartProps extends BaseComponentProps<ChipStartInstance, unknown, ChipStartPassThrough> {
}
/**
 * Defines valid state in ChipStart component.
 */
export interface ChipStartState {
}
/**
 * Defines the methods and properties exposed by ChipStart component.
 */
export interface ChipStartExposes {
    /**
     * The Chip component instance.
     */
    chip: ChipRootInstance | undefined | null;
}
/**
 * Instance of ChipStart component.
 */
export type ChipStartInstance = ComponentInstance<ChipStartProps, ChipStartState, ChipStartExposes>;
